using Microsoft.EntityFrameworkCore;

// Cosmos DB companion project – breaking-change fixes for EF Core 9.
class CosmosDbContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();

    protected override void OnConfiguring(DbContextOptionsBuilder options)
    {
        options.UseCosmos(
            "AccountEndpoint=https://localhost:8081/;AccountKey=...",
            "CatalogDb");
    }

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // FIX 1 – Discriminator property renamed from "Discriminator" to "$type"
        // in EF Core 9. Existing documents already store "Discriminator", so
        // explicitly set the property name to keep compatibility.
        modelBuilder.Entity<Product>().HasDiscriminator<string>("Discriminator");

        // FIX 2 – Synchronous Cosmos I/O now throws by default.
        // All queries / SaveChanges calls must use async variants:
        //   BEFORE: db.Products.ToList()        → AFTER: await db.Products.ToListAsync()
        //   BEFORE: db.SaveChanges()            → AFTER: await db.SaveChangesAsync()
    }
}

class Product
{
    public string Id { get; set; } = default!;
    public string Name { get; set; } = default!;
}

